import unittest
from unittest.mock import patch, MagicMock

class SymptomManager:
    def __init__(self):
        self.symptoms = {}

    def add_symptom(self, name, description):
        if name in self.symptoms:
            raise ValueError("Symptom already exists")
        self.symptoms[name] = description

    def get_symptom(self, name):
        return self.symptoms.get(name)

    def update_symptom(self, name, description):
        if name not in self.symptoms:
            raise ValueError("Symptom does not exist")
        self.symptoms[name] = description

    def delete_symptom(self, name):
        if name not in self.symptoms:
            raise ValueError("Symptom does not exist")
        if any(symptom == name for consultation in self.consultations.values()):
            raise ValueError("Symptom is used in a consultation request")
        del self.symptoms[name]

    def add_consultation(self, consultation_id, symptoms):
        self.consultations[consultation_id] = symptoms

class TestSymptomManager(unittest.TestCase):
    def setUp(self):
        self.manager = SymptomManager()

    def test_add_symptom_positive(self):
        self.manager.add_symptom("fever", "High body temperature")
        self.assertIn("fever", self.manager.symptoms)

    def test_add_symptom_negative_duplicate(self):
        self.manager.add_symptom("fever", "High body temperature")
        with self.assertRaises(ValueError):
            self.manager.add_symptom("fever", "High body temperature")

    def test_get_symptom_positive(self):
        self.manager.add_symptom("fever", "High body temperature")
        self.assertEqual(self.manager.get_symptom("fever"), "High body temperature")

    def test_get_symptom_negative_nonexistent(self):
        with self.assertRaises(ValueError):
            self.manager.get_symptom("fever")

    def test_update_symptom_positive(self):
        self.manager.add_symptom("fever", "High body temperature")
        self.manager.update_symptom("fever", "Increased body temperature")
        self.assertEqual(self.manager.get_symptom("fever"), "Increased body temperature")

    def test_update_symptom_negative_nonexistent(self):
        with self.assertRaises(ValueError):
            self.manager.update_symptom("fever", "Increased body temperature")

    def test_delete_symptom_positive(self):
        self.manager.add_symptom("fever", "High body temperature")
        self.manager.delete_symptom("fever")
        self.assertNotIn("fever", self.manager.symptoms)

    def test_delete_symptom_negative_nonexistent(self):
        with self.assertRaises(ValueError):
            self.manager.delete_symptom("fever")

    def test_delete_symptom_negative_used_in_consultation(self):
        self.manager.add_symptom("fever", "High body temperature")
        self.manager.add_consultation("1", ["fever"])
        with self.assertRaises(ValueError):
            self.manager.delete_symptom("fever")

    def test_add_consultation_positive(self):
        self.manager.add_consultation("1", ["fever"])
        self.assertIn("1", self.manager.consultations)

if __name__ == '__main__':
    unittest.main()
